'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { Bot, BarChart2, ScrollText, Users } from 'lucide-react'

export function Navbar() {
    const pathname = usePathname()

    const routes = [
        {
            href: '/',
            label: 'Home',
            icon: Users,
        },
        {
            href: '/scout/match',
            label: 'Match Scout',
            icon: ScrollText,
        },
        {
            href: '/scout/pit',
            label: 'Pit Scout',
            icon: Bot,
        },
        {
            href: '/analytics',
            label: 'Analytics',
            icon: BarChart2,
        },
    ]

    return (
        <nav className="border-b bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60 sticky top-0 z-50">
            <div className="container flex h-16 items-center px-4 mx-auto">
                <div className="mr-4 hidden md:flex">
                    <Link href="/" className="mr-6 flex items-center space-x-2">
                        <Bot className="h-6 w-6" />
                        <span className="hidden font-bold sm:inline-block">
                            Metal Cow Scouting
                        </span>
                    </Link>
                    <nav className="flex items-center space-x-6 text-sm font-medium">
                        {routes.map((route) => (
                            <Link
                                key={route.href}
                                href={route.href}
                                className={cn(
                                    "transition-colors hover:text-foreground/80",
                                    pathname === route.href ? "text-foreground" : "text-foreground/60"
                                )}
                            >
                                {route.label}
                            </Link>
                        ))}
                    </nav>
                </div>

                {/* Mobile Nav could be implemented here via Sheet or simpler approach */}
                <div className="flex md:hidden w-full justify-between items-center text-sm">
                    <span className="font-bold">Metal Cow</span>
                    <div className="flex gap-4">
                        {routes.map((route) => (
                            <Link key={route.href} href={route.href}>
                                <route.icon className={cn("h-5 w-5", pathname === route.href ? "text-primary" : "text-muted-foreground")} />
                            </Link>
                        ))}
                    </div>
                </div>

                <div className="flex flex-1 items-center justify-end space-x-2">
                    <Button variant="ghost" size="sm">Login</Button>
                </div>
            </div>
        </nav>
    )
}
